package net.officefloor.hq.app.person;

import java.time.LocalDate;
import java.util.List;

/**
 * A person on a sheet. {@code grade} (one of A, B or C) is the first grade they were given, which applies
 * from the beginning of time; {@code dated} are the grades given since, each from its date on, by date.
 * {@code version} is raised on every edit. {@code retiredFrom} is the date they are retired from (null when
 * not retired); a person with one set is retired at once, whatever the date. {@code holds} are their holds, by
 * from-date: their OPEN claims dated within one, unless bound by a statement, count in no live total.
 */
public record Person(long id, String sheetId, String name, String grade, long version, LocalDate retiredFrom,
        List<Hold> holds, List<DatedGrade> dated) {

    public Person with(PersonRequest request) {
        return new Person(id, sheetId, request.name(), grade, version + 1, retiredFrom, holds, dated);
    }

    /** The grade in force on the date: the one with the latest from-date on or before it, else the first grade. */
    public String gradeOn(LocalDate date) {
        String on = grade;
        for (DatedGrade d : dated) {
            if (!d.from().isAfter(date)) {
                on = d.grade();
            }
        }
        return on;
    }

    /** Whether the person has any hold. */
    public boolean held() {
        return !holds.isEmpty();
    }

    /** Whether the date falls within any of the person's holds. */
    public boolean heldOn(LocalDate date) {
        return holds.stream().anyMatch(h -> h.covers(date));
    }

    public boolean retired() {
        return retiredFrom != null;
    }
}
package net.officefloor.hq.app.person;

/**
 * The body of an add or an edit of a person: the name as typed and the grade (A, B or C). An edit
 * also names the {@code version} its form loaded (null on an add), and {@code gradeFrom}, the date
 * (yyyy-mm-dd) the grade is given from, blank for the sheet's today. An add's grade is the first one,
 * which applies from the beginning of time, so it ignores {@code gradeFrom}.
 */
public record PersonRequest(String name, String grade, Long version, String gradeFrom) {
}
package net.officefloor.hq.app.person;

import java.time.LocalDate;
import java.util.ArrayList;
import java.util.List;

/**
 * A person as the screen sees it. {@code grade} is the grade in force on the sheet's today; {@code grades} are
 * all the grades they were given, by from-date (yyyy-mm-dd; null for the first, from the beginning of time).
 * {@code retiredFrom} is yyyy-mm-dd, null when not retired; {@code held} is whether they have any
 * hold; {@code holds} are their holds by from-date (yyyy-mm-dd; {@code to} null when it has no end).
 */
public record PersonResponse(long id, String name, String grade, List<Graded> grades, long version,
        String retiredFrom, boolean held, List<Held> holds) {

    public record Graded(String from, String grade) {
    }

    public record Held(String from, String to) {
    }

    public static PersonResponse from(Person person, LocalDate today) {
        List<Graded> grades = new ArrayList<>();
        grades.add(new Graded(null, person.grade()));
        person.dated().forEach(d -> grades.add(new Graded(d.from().toString(), d.grade())));
        return new PersonResponse(person.id(), person.name(), person.gradeOn(today), grades, person.version(),
                person.retiredFrom() == null ? null : person.retiredFrom().toString(), person.held(),
                person.holds().stream().map(h -> new Held(h.from().toString(), h.to() == null ? null : h.to().toString()))
                        .toList());
    }
}
package net.officefloor.hq.app.person;

import java.time.LocalDate;
import java.time.format.DateTimeFormatter;
import java.time.format.DateTimeParseException;
import java.time.format.ResolverStyle;
import java.util.Set;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.RequestBody;

public class ValidatePerson {

    private static final DateTimeFormatter ISO = DateTimeFormatter.ofPattern("uuuu-MM-dd")
            .withResolverStyle(ResolverStyle.STRICT);

    private static final Set<String> GRADES = Set.of("A", "B", "C");

    // The name is kept without surrounding spaces; a blank one is refused.
    public void validate(@RequestBody PersonRequest body, Out<PersonRequest> request) throws InvalidPersonException {
        String name = body == null || body.name() == null ? "" : body.name().trim();
        String grade = body == null || body.grade() == null ? "" : body.grade().trim();
        if (name.isEmpty()) {
            throw new InvalidPersonException("Type a name.");
        }
        if (!GRADES.contains(grade)) {
            throw new InvalidPersonException("The grade must be A, B or C.");
        }
        // A blank from-date is kept null: the sheet's today, filled in when stored.
        String from = body.gradeFrom() == null ? "" : body.gradeFrom().trim();
        if (!from.isEmpty()) {
            try {
                LocalDate.parse(from, ISO);
            } catch (DateTimeParseException e) {
                throw new InvalidPersonException("Not a date (yyyy-mm-dd): " + from);
            }
        }
        request.set(new PersonRequest(name, grade, body.version(), from.isEmpty() ? null : from));
    }
}
